"use strict";

// Fixed vectors generated by scripts/gen_device_wrap_vectors.py (rev 2:
// targets[] format). These pin the WebCrypto chain: HKDF parameters, P-256
// ECDH over raw points, AES-GCM AAD framing, keyId derivation from the
// credential, and the QRFT chunk round-trip. If any line fails here, the
// extension and the Android app disagree on the wire format.
const V = {
  prfOut: "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f",
  credId: "ICEiIyQlJicoKSorLC0uLzAxMjM0NTY3ODk6Ozw9Pj8=",
  keyId: "72dbb7336c767800",                 // R1: hex(SHA-256(credId))[0..8]
  salt: "q5oYXr3CRo9//Fj24tuSuUAAIqOrkORNlkzE7krAbYg=",
  seedPubRaw: "0420eb2418a4d73b6e941055d4e4c27d3cefe2363114dbc0520489f9bfc314d27d6fd4da9b14eb530e95449d24b9124f98dc2ca4feb3b2a5d8ac1c2549e567a1c8",
  seedIv: "000102030405060708090a0b",
  seedCt: "cNRWuEn/6w2MxYuagfKPeiz4T1JW25sXSZ8Ggtf5md8D3B9yFzq9uSGKNefXXE1REV3pNZghf+eW8Y9UuhZ49ARVuuubi7W9w1dZgK51FgT7Kl3zU93xguKFvXhhJgCir8EGm7zrRMYgs1HrMB4mYe9k6kGIvX/viWNt2nEq3abQBVhJMXN+7CZiCTuou+uBOcbQmcCqwJsx8w==",
  kek: "f3b81f2432825d28b4cf8940da95543198f0aa0aab6bde7f64d29476716d9568",
  sharedX: "0316c0e78d036219f2dc2d4813812625c68d6550361578cf3fc1c71b5f7f99e4",
  wrapKek: "0148f944db44d0de74b4c1f52ea99e675afe35f827c5af9e4cb09c611447dcaf",
  cek: "606162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f",
  payloadIv: "0102030405060708090a0b0c",
  payloadCt: "",
  target1: {
    keyId: "72dbb7336c767800",
    epk: "BJp4HKbQVafzDQyf+Hk2xzn2gW719ecrS5RkBLChqDsqwZ+EKUXqK/ZaoWSbKwL/eYVMjV7PzUA4YuipfqZsccE=",
    iv: "AAECAwQFBgcICQoL",
    ct: "sXfCVNY7rbqdxEnqunN4eaD0OihCLT8j8Jfg3LAE5zAvkfzbMM25St9DiJqNwMn3"
  },
  target2: {
    keyId: "ca2a4fe727faaecf",
    epk: "BD+Vxfbt9v4Fx+Jp70KOphYUv0VvAWjdtGQXDmt2h0kanE+acKIkUzswe8fPd2Zoj9I+rFB56aqI9SRLA9FElRA=",
    iv: "EBESExQVFhcYGRob",
    ct: "wE8HlyTS7wSSIrNijKCBP3d0+aspPxEyNOgneGJoVDCVRJ/IjHNiX7hWYk7IFZDf"
  },
  payloadIvB64: "AQIDBAUGBwgJCgsM",
  payload: '{"itemId":"vec-item-0000","shareId":"local","data":{"type":"login","metadata":{"name":"Vector Test","itemUuid":"vec-item-0000"},"content":{"itemEmail":"","itemUsername":"vector","password":"s3cret-vector","urls":["https://example.test"],"totpUri":"","passkeys":[]}},"state":1}'
};

// The full 2-target wrapped paste (assembled after V to avoid self-reference).
const W = {
  v: 1, type: "offlinepass-wrap",
  payload: { iv: V.payloadIvB64, ct: V.payloadCt },
  targets: [V.target1, V.target2],
};

const out = document.getElementById("out");
function line(ok, label, extra) {
  const d = document.createElement("div");
  d.className = ok ? "ok" : "fail";
  d.textContent = (ok ? "PASS " : "FAIL ") + label + (extra ? " — " + extra : "");
  out.append(d);
}

async function main() {
  try {
    const credId = LpWrap.unb64(V.credId);

    // 1. R1: stable identity — keyId from the credential
    const keyId = await LpWrap.keyIdFor(credId);
    line(keyId === V.keyId, "keyId derivation (from credId)");

    // 2. PRF salt + seed KEK
    const salt = await LpWrap.prfSalt(credId);
    line(LpWrap.b64(salt) === V.salt, "prf salt derivation");
    const kek = await LpWrap.hkdf(LpWrap.hexToBytes(V.prfOut), salt, LpWrap.SEED_INFO, 32);
    line(LpWrap.bytesToHex(kek) === V.kek, "seed KEK (HKDF)");

    // 3. unwrap the seed (AES-GCM under KEK) → import pkcs8
    const pkcs8 = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv: LpWrap.hexToBytes(V.seedIv), additionalData: LpWrap.SEED_AAD },
      await crypto.subtle.importKey("raw", kek, { name: "AES-GCM" }, false, ["decrypt"]),
      LpWrap.unb64(V.seedCt));
    const seedPriv = await crypto.subtle.importKey(
      "pkcs8", pkcs8, { name: "ECDH", namedCurve: "P-256" }, false, ["deriveBits"]);

    // 4. the REAL decrypt path (targets[] matching included), no touch —
    //    the seed comes from the vector instead of the WebAuthn ceremony.
    const record = {
      keyId: V.keyId, name: "vector-key", credId: V.credId, salt: V.salt,
      wrapped: { iv: LpWrap.b64(LpWrap.hexToBytes(V.seedIv)), ct: V.seedCt },
    };
    const plain = await LpWrap.unwrapPasteWithSeed(seedPriv, record, JSON.stringify(W));
    line(plain === V.payload, "wrapped paste decrypt (2-target format)");

    // 5. a paste with no target for our key must fail loudly
    let rejected = false;
    try {
      const wrong = { v: 1, type: "offlinepass-wrap", payload: W.payload, targets: [V.target2] };
      await LpWrap.unwrapPasteWithSeed(seedPriv, record, JSON.stringify(wrong));
    } catch (e) { rejected = true; }
    line(rejected, "no-matching-target rejected");

    // 6. QRFT frame round-trip (encode like generator, decode like scanner)
    const text = '{"a":"' + "x".repeat(600) + '"}';
    const frames = LpQrft.buildFrames("selftest", text);
    const r = new LpQrft.Reassembler();
    let res = null;
    for (const f of frames) { const x = r.push(f); if (x) res = x; }
    line(!!res && res.text === text, "QRFT frame round-trip");

    line(true, "self-test complete");
  } catch (e) {
    line(false, "self-test aborted", String(e && e.message || e));
  }
}
main();